import unittest
from candidate import is_palindrome


class TestIsPalindrome(unittest.TestCase):
    def test_empty_string_returns_true(self):
        self.assertTrue(is_palindrome(''))

    def test_single_character_returns_true(self):
        self.assertTrue(is_palindrome('a'))

    def test_two_identical_characters_returns_true(self):
        self.assertTrue(is_palindrome('aa'))

    def test_two_different_characters_returns_false(self):
        self.assertFalse(is_palindrome('ab'))

    def test_aba_palindrome_returns_true(self):
        self.assertTrue(is_palindrome('aba'))

    def test_aaaaa_palindrome_returns_true(self):
        self.assertTrue(is_palindrome('aaaaa'))

    def test_zbcd_non_palindrome_returns_false(self):
        self.assertFalse(is_palindrome('zbcd'))

    def test_even_length_palindrome_returns_true(self):
        self.assertTrue(is_palindrome('abba'))

    def test_even_length_non_palindrome_returns_false(self):
        self.assertFalse(is_palindrome('abab'))

    def test_single_letter_palindrome_returns_true(self):
        self.assertTrue(is_palindrome('z'))

    def test_all_same_chars_returns_true(self):
        self.assertTrue(is_palindrome('cccccc'))

    def test_numeric_string_palindrome_returns_true(self):
        self.assertTrue(is_palindrome('12321'))

    def test_numeric_string_non_palindrome_returns_false(self):
        self.assertFalse(is_palindrome('12345'))

    def test_case_sensitive_palindrome_returns_false(self):
        self.assertFalse(is_palindrome('Aba'))

    def test_case_sensitive_palindrome_upper_returns_false(self):
        self.assertFalse(is_palindrome('aBA'))

    def test_spaces_not_ignored_palindrome(self):
        self.assertTrue(is_palindrome('a a'))

    def test_spaces_not_ignored_non_palindrome(self):
        self.assertFalse(is_palindrome('ab ba'))

    def test_unicode_palindrome_returns_true(self):
        self.assertTrue(is_palindrome('éàé'))

    def test_unicode_non_palindrome_returns_false(self):
        self.assertFalse(is_palindrome('éàb'))

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_palindrome(None)

    def test_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_palindrome(12321)

    def test_list_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_palindrome(['a', 'b', 'a'])

    def test_long_palindrome_returns_true(self):
        s = 'a' * 1001
        self.assertTrue(is_palindrome(s))

    def test_long_non_palindrome_returns_false(self):
        s = 'a' * 500 + 'b' + 'a' * 500
        self.assertTrue(is_palindrome(s))

    def test_first_and_last_mismatch_returns_false(self):
        self.assertFalse(is_palindrome('abcdef'))

    def test_middle_mismatch_returns_false(self):
        self.assertFalse(is_palindrome('abxba'))

    def test_tab_character_palindrome_returns_true(self):
        self.assertTrue(is_palindrome('\t\t'))

    def test_newline_palindrome_returns_true(self):
        self.assertTrue(is_palindrome('\n\n'))

    def test_return_type_is_bool_true(self):
        self.assertIsInstance(is_palindrome('aba'), bool)
        self.assertTrue(is_palindrome('aba'))

    def test_return_type_is_bool_false(self):
        self.assertIsInstance(is_palindrome('abc'), bool)
        self.assertFalse(is_palindrome('abc'))


if __name__ == '__main__':
    unittest.main()
